25	package jenkins.model;
26	
27	import hudson.Extension;
28	import hudson.model.AsyncPeriodicWork;
29	import hudson.model.Job;
30	import hudson.model.TaskListener;
31	import java.io.IOException;
32	import java.util.logging.Level;
33	import java.util.logging.Logger;
34	import org.kohsuke.accmod.Restricted;
35	import org.kohsuke.accmod.restrictions.NoExternalUse;
36	
37	/**
38	 * Background task actually running background build discarders.
39	 *
40	 * @see GlobalBuildDiscarderConfiguration
41	 * @see GlobalBuildDiscarderStrategy
42	 */
43	@Restricted(NoExternalUse.class)
44	@Extension
45	public class BackgroundGlobalBuildDiscarder extends AsyncPeriodicWork {
46	    private static final Logger LOGGER = Logger.getLogger(BackgroundGlobalBuildDiscarder.class.getName());
47	
48	    public BackgroundGlobalBuildDiscarder() {
49	        super("Periodic background build discarder"); // TODO i18n
50	    }
51	
52	    @Override
53	    protected void execute(TaskListener listener) throws IOException, InterruptedException {
54	        for (Job job : Jenkins.get().allItems(Job.class)) {
55	            processJob(listener, job);
56	        }
57	    }
58	
59	    public static void processJob(TaskListener listener, Job job) {
60	        listener.getLogger().println("Processing " + job.getFullName());
61	        GlobalBuildDiscarderConfiguration.get().getConfiguredBuildDiscarders().forEach(strategy -> {
62	            String displayName = strategy.getDescriptor().getDisplayName();
63	            listener.getLogger().println("Offering " + job.getFullName() + " to " + displayName);
64	            if (strategy.isApplicable(job)) {
65	                listener.getLogger().println(job.getFullName() + " accepted by " + displayName);
66	                try {
67	                    strategy.apply(job);
68	                } catch (Exception ex) {
69	                    listener.error("An exception occurred when executing " + displayName + ": " + ex.getMessage());
70	                    LOGGER.log(Level.WARNING, "An exception occurred when executing " + displayName, ex);
71	                }
72	            }
73	        });
74	    }
75	
76	    @Override
77	    public long getRecurrencePeriod() {
78	        return HOUR;
79	    }
80	}
